  arbitre: g => { g.hall(); for (let i = 0; i < 9; i++){ const a = (.1 + i * .8 / 8) * Math.PI; g.A(200 + 165 * Math.cos(a), 62 + 150 * Math.sin(a)); } g.P(200, 70);
    return g.tag(200, 36, 'main ? tacle ? touche ? corner ?', {s: 10}).label(200, 130, 'la classe fait le geste de l\'arbitre', {s: 10, b: 1})
      .n(1, 'le prof mime une action, la classe fait le geste de l\'arbitre').n(2, 'puis l\'inverse : le prof fait le geste, un élève mime la faute'); },
  'Les phases finales': g => { g.terrains(2, {goals: 'foot', labs: ['finale 🏆', 'match pour la 3e place'], h: 190, y0: 12}); g.T.forEach(([x, y, w, h]) => g.scatter('a', 4, x + 15, y + 30, x + w / 2 - 8, y + h - 15, {seed: 3}).scatter('b', 4, x + w / 2 + 8, y + 30, x + w - 15, y + h - 15, {seed: 5}));
    return g.bord(60, 232, 3, '', 'g').sheet(150, 232).chrono(175, 232).label(270, 232, 'au repos : arbitres, table, chrono', {s: 9}).n(1, 'toutes les places se jouent ; égalité = tirs au but'); }
